-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (통화 표들의 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261026160000' and name='call_context_people')=1 then '예' else '아니오' end as value
union all select 'function: definer, stable, empty search_path, execute only service_role',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_call_context_people(uuid,integer)') and p.prosecdef and p.provolatile='s' and p.proconfig=array['search_path=""'] and has_function_privilege('service_role',p.oid,'execute') and not has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'function returns only four name-level columns',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_call_context_people(uuid,integer)') and p.proargnames=array['p_workspace','p_limit','organization_name','organization_aliases','counterpart','user_edited'] and p.proargmodes=array['i','i','t','t','t','t']::"char"[]) then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the call tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'service_role still has no direct read of the call edits table',case when not has_any_column_privilege('service_role','public.app_call_edits','select') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'call edits rows',(select count(*)::text from public.app_call_edits)
union all select 'call tables grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations')) ),'')
  ||coalesce((select string_agg(c.relname::text||'.'||a.attname::text||':'||a.attacl::text,',' order by c.relname,a.attname) from pg_attribute a join pg_class c on c.oid=a.attrelid where a.attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations')) and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations'))),''));
